    deps.runlog.noteRun(
      target.project,
      [target.file],
      report.diagnostics.filter((d) => !old.includes(d)),
    );
    deps.runlog.noteSuppressions(report, rejected);
    const session = { project: target.project, id };
    const escalation = escalationOf(io, session, configPath, blocking);
